```python
import heapq

def find_set(parent, i):
    if parent[i] != i:
        parent[i] = find_set(parent, parent[i])
    return parent[i]

def union_sets(parent, rank, x, y):
    xroot = find_set(parent, x)
    yroot = find_set(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def kruskal(graph):
    n = len(graph)
    parent = [i for i in range(n)]
    rank = [0] * n
    edges = []

    for u in graph:
        for v, w in graph[u].items():
            edges.append((w, u, v))

    edges.sort()

    result = []
    for w, u, v in edges:
        if find_set(parent, u) != find_set(parent, v):
            union_sets(parent, rank, u, v)
            result.append((u, v))

    return result

# Example usage
graph = {0: {1: 2, 2: 3}, 1: {0: 2, 3: 1}, 2: {0: 3, 3: 2}, 3: {1: 1, 2: 2}}
print(kruskal(graph))  # Output: [(0, 1), (1, 3), (0, 2)]
```

This program first initializes the parent list and rank array with the indices of the vertices and set their ranks to 0. Then, it adds all the edges to the `edges` list, sorts them by weight, and iterates through them to find the minimum spanning tree. The `union_sets` function is used to merge the sets of connected vertices, and the `find_set` function is used to check if two vertices are in the same set.
